def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    cindy_like_high = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) <= 110:
                    dangerous_prev.append(float(bid))
                else:
                    cindy_like_high.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    alive_count = len(alive)
    units = supply / float(WATER_REQ)
    scarcity = alive_count - units

    need_urgent = hp <= 3 or no_water_days >= 1
    need_critical = hp <= 2 or no_water_days >= 2

    baseline = 32.0
    if scarcity >= 2.5:
        baseline = 58.0
    elif scarcity >= 1.5:
        baseline = 48.0
    elif scarcity >= 0.5:
        baseline = 40.0
    else:
        baseline = 28.0

    if dangerous_prev:
        target = max(dangerous_prev) + 2.0
    elif prev_bids:
        target = min(max(prev_bids) * 0.45, 65.0)
    else:
        target = baseline

    bid = max(baseline, target)

    if supply <= 16:
        bid += 8.0
    elif supply >= 23:
        bid -= 6.0

    if need_urgent:
        bid = max(bid, 62.0)
    if need_critical:
        bid = max(bid, 82.0)

    if hp >= 8 and no_water_days == 0 and supply >= 22 and dangerous_prev:
        bid = min(bid, max(dangerous_prev) - 3.0)

    reserve = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    cap = max(0.0, budget - reserve)
    if need_critical:
        cap = budget
    elif need_urgent:
        cap = max(cap, budget * 0.72)

    bid = min(bid, cap)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Determine alive opponents and extract yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate market pressure from yesterday
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Supply pressure: if supply is scarce, we must secure water
    # Normalize supply to [0,1] where 1 means scarce
    if MAX_SUPPLY <= MIN_SUPPLY:
        scarcity = 0.5
    else:
        scarcity = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if scarcity < 0.0:
            scarcity = 0.0
        if scarcity > 1.0:
            scarcity = 1.0

    # Health urgency
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Target bid: aim to outbid the likely overbidder only when needed
    # Use a cap to avoid bankruptcy.
    # If Cindy-type behavior exists (very high highest_prev_bid), we don't match it; we bid enough to win at lower cost.
    base = DAILY_SALARY * (0.35 + 0.45 * scarcity)

    # If my hp is low, bid more aggressively
    if hp <= 1.5:
        urgency_mult = 1.9
    elif hp <= 3.5:
        urgency_mult = 1.35
    else:
        urgency_mult = 1.0

    # If highest_prev_bid is extremely high, assume someone is overbidding; don't chase fully.
    # Instead, bid just above a fraction of it.
    if highest_prev_bid > DAILY_SALARY * 1.2:
        chase = second_prev_bid * 0.95 + 2.0
        target = min(base * urgency_mult, chase)
    else:
        # Normal pressure: hover near highest_prev_bid but with discount
        target = min(base * urgency_mult, highest_prev_bid * 0.92 + 3.0)

    # Ensure we don't bid more than budget
    if budget <= 0.0:
        return 0.0

    # Also ensure minimal competitive bid when supply is scarce
    min_competitive = DAILY_SALARY * (0.25 + 0.35 * scarcity)
    bid = max(target, min_competitive if scarcity >= 0.4 else target * 0.8)

    if bid > budget:
        bid = budget

    # Final safety clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

